import sys

data = sys.stdin.read().split()
n, m, k = int(data[0]), int(data[1]), int(data[2])
cps = set()
for i in range(k):
    cps.add((int(data[3 + 2 * i]), int(data[4 + 2 * i])))
MOD = 10**9 + 7
# state: (row, number of checkpoints visited so far) -> number of paths
cur = {(n - 1, 1 if (n - 1, 0) in cps else 0): 1}
for c in range(1, m):
    nxt = {}
    for (r, seen), w in cur.items():
        for dr in (-1, 0, 1):
            nr = r + dr
            if 0 <= nr < n:
                key = (nr, seen + (1 if (nr, c) in cps else 0))
                nxt[key] = (nxt.get(key, 0) + w) % MOD
    cur = nxt
print(cur.get((n - 1, len(cps)), 0) % MOD)

